/**
 * A cena do `fog-garden`: uma trilha sinuosa num jardim na névoa, percorrida
 * pela câmera conforme o progresso.
 *
 * Mesma floresta do `fog-tree` (mesmos cinzas, mesmo `growTree`, mesmo
 * `fog-post`), outra escala: dezenas de árvores em vez de uma. O que torna isso
 * viável num notebook é a decisão 1.
 *
 * 1. **Sete árvores geradas, dezenas plantadas.** O ez-tree gera geometria na
 *    thread principal (dezenas de ms por árvore). Aqui nascem sete variantes,
 *    uma vez, e cada árvore da trilha é um `Group` com malhas que APONTAM para
 *    a geometria e o material da variante — memória de sete, custo de upload de
 *    sete. E o vento vem de graça: o uniform de tempo mora no material
 *    compartilhado, então atualizar a variante balança todos os clones dela.
 * 2. **Clone na mão, não `tree.clone()`.** O construtor do `Tree` cria duas
 *    malhas vazias; o `clone()` do three chama esse construtor e DEPOIS copia os
 *    filhos, então cada clone carregava duas malhas fantasmas com material
 *    próprio que ninguém descartava.
 * 3. **Semente fixa.** O plantio usa um LCG semeado: o jardim é o mesmo a cada
 *    visita e em toda máquina. Jardim que muda a cada recarga faz a pessoa
 *    achar que a página está quebrando, não que é generativa.
 * 4. **Clareiras são parâmetro.** Perto delas o plantio rareia e entra uma
 *    árvore protagonista (a copa redonda) ao lado da trilha, para a câmera
 *    passar perto. Os marcos (`landmark`) vêm de fora: a cena não sabe o que é
 *    o produto de ninguém.
 */

import * as THREE from "three";
import type { Tree } from "@dgreenheck/ez-tree";

import type { RGB } from "@/lib/css-color";
import {
  contactShadowTexture,
  createFogPost,
  createFogRenderer,
  disposeTree,
  gray,
  releaseRenderer,
} from "@/lib/fog-post";
import { growTree, roundCrown } from "@/lib/fog-tree-scene";

/**
 * Fábrica de marco para as clareiras (um objeto, um produto, uma escultura).
 *
 * Recebe o índice da clareira e devolve o objeto em unidades da cena (uma
 * árvore de fundo tem ~25 de altura; a câmera anda a 13 do chão). A cena
 * posiciona, gira `userData.spin` rad/s se houver, e DESCARTA geometria e
 * material do que for devolvido no fim — não reaproveite fora daqui.
 */
export type GardenLandmark = (index: number) => THREE.Object3D | null | undefined;

export interface GardenSceneOptions {
  seed: number;
  /** Quantas posições de plantio ao longo da trilha. */
  density: number;
  /** Pontos 0..1 da trilha com clareira. */
  clearings: number[];
  landmark?: GardenLandmark;
  trail: number;
  grain: number;
  reduce: boolean;
  light: boolean;
}

export interface GardenScene {
  setProgress(p: number): void;
  /** Ponteiro em -1..1; desvia o olhar da câmera para os lados. */
  setPointer(x: number, y: number): void;
  setColors(paper: RGB, ink: RGB): void;
  setRunning(on: boolean): void;
  dispose(): void;
}

// LCG de Numerical Recipes: curto, rápido e igual em todo motor JS
function rng(seed: number) {
  let s = seed >>> 0;
  return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
}

/** Um "clone" que compartilha geometria e material com a variante (decisão 2). */
function instance(base: Tree) {
  const g = new THREE.Group();
  for (const m of [base.branchesMesh, base.leavesMesh]) {
    g.add(new THREE.Mesh(m.geometry, m.material));
  }
  return g;
}

export function createGardenScene(
  canvas: HTMLCanvasElement,
  opts: GardenSceneOptions,
): GardenScene | null {
  const renderer = createFogRenderer(canvas, opts.light);
  if (!renderer) return null;

  const scene = new THREE.Scene();
  const branco = gray(1);
  scene.background = branco;
  // densidade absoluta: o jardim tem escala fixa, diferente da árvore sozinha
  scene.fog = new THREE.FogExp2(branco, 0.0042);

  const camera = new THREE.PerspectiveCamera(42, 1, 0.5, 900);
  scene.add(new THREE.HemisphereLight(branco, gray(0.604), 2.2));
  const sol = new THREE.DirectionalLight(branco, 1.1);
  sol.position.set(40, 120, 60);
  scene.add(sol);

  // Trilha: senoide suave em profundidade. `centripetal` evita a laçada que a
  // Catmull-Rom uniforme faz quando dois pontos ficam próximos demais.
  const pontos = Array.from(
    { length: 14 },
    (_, i) => new THREE.Vector3(Math.sin(i * 0.85) * 55, 0, -i * 210),
  );
  const trilha = new THREE.CatmullRomCurve3(pontos, false, "centripetal");

  const chaoGeo = new THREE.PlaneGeometry(6000, 6000);
  const chaoMat = new THREE.MeshBasicMaterial({ color: gray(0.957) });
  const chao = new THREE.Mesh(chaoGeo, chaoMat);
  chao.rotation.x = -Math.PI / 2;
  chao.position.z = -1300;
  scene.add(chao);

  // Uma textura, uma geometria e um material de sombra para o jardim inteiro;
  // o tamanho de cada sombra vem da escala da malha.
  const sombraTex = contactShadowTexture(128, 0.32);
  const sombraGeo = new THREE.PlaneGeometry(1, 1);
  const sombraMat = new THREE.MeshBasicMaterial({
    map: sombraTex,
    transparent: true,
    depthWrite: false,
  });

  // Variantes (decisão 1). Folha mais rala nas de fundo: elas passam ao longe,
  // na névoa densa, e a contagem de folha é o grosso dos vértices.
  const folhas = opts.light ? 10 : 16;
  const rala = (t: Tree) => {
    t.options.leaves.count = folhas;
  };
  const protagonista = growTree("Oak Medium", 4242, roundCrown);
  const fundo = [
    growTree("Oak Medium", 11, rala),
    growTree("Ash Medium", 23, rala),
    growTree("Aspen Medium", 37, rala),
    growTree("Oak Small", 51, rala),
  ];
  const arbustos = [growTree("Bush 1", 7), growTree("Bush 2", 9)];
  const variantes = [protagonista, ...fundo, ...arbustos];
  const tamanho = new Map(
    variantes.map((v) => [v, new THREE.Box3().setFromObject(v).getSize(new THREE.Vector3())]),
  );

  const plantar = (base: Tree, pos: THREE.Vector3, escala: number, rot: number) => {
    const c = instance(base);
    c.position.copy(pos);
    c.scale.setScalar(escala);
    c.rotation.y = rot;
    scene.add(c);
    const tam = tamanho.get(base)!;
    const s = new THREE.Mesh(sombraGeo, sombraMat);
    s.rotation.x = -Math.PI / 2;
    s.position.set(pos.x, 0.05, pos.z);
    s.scale.set(tam.x * escala * 1.4, tam.z * escala * 1.1, 1);
    scene.add(s);
  };

  const tangente = new THREE.Vector3();
  const lado = new THREE.Vector3();
  /** Ponto da trilha deslocado para o lado (perpendicular à tangente, no chão). */
  const aoLado = (u: number, desvio: number, out = new THREE.Vector3()) => {
    trilha.getPointAt(THREE.MathUtils.clamp(u, 0, 1), out);
    trilha.getTangentAt(THREE.MathUtils.clamp(u, 0, 1), tangente);
    lado.set(-tangente.z, 0, tangente.x).normalize();
    return out.addScaledVector(lado, desvio);
  };

  // Plantio (decisão 3): mais ralo perto das clareiras, arbusto perto da
  // trilha e árvore mais longe, para a trilha ler como caminho aberto.
  const r = rng(opts.seed);
  const passos = Math.max(8, Math.round(opts.light ? opts.density * 0.6 : opts.density));
  for (let k = 0; k < passos; k++) {
    const u = 0.02 + (k / passos) * 0.97;
    const perto = opts.clearings.some((c) => Math.abs(c - u) < 0.035);
    if (perto && r() < 0.8) continue;
    const sinal = r() < 0.5 ? -1 : 1;
    const arbusto = r() < 0.3;
    const dist = arbusto ? 18 + r() * 26 : 50 + r() * 110;
    const base = arbusto
      ? arbustos[(r() * arbustos.length) | 0]
      : fundo[(r() * fundo.length) | 0];
    const escala = arbusto ? 1.2 + r() * 1.2 : 0.75 + r() * 0.6;
    plantar(base, aoLado(u, sinal * dist), escala, r() * Math.PI * 2);
  }

  // Protagonista em cada clareira, alternando o lado, um pouco à frente do
  // ponto: a câmera olha adiante, então a árvore entra no quadro ANTES de a
  // câmera chegar, e não de lado quando já passou.
  const marcos: THREE.Object3D[] = [];
  opts.clearings.forEach((u, i) => {
    const flanco = i % 2 ? 1 : -1;
    plantar(protagonista, aoLado(u + 0.012, flanco * 26), 1, i * 1.7);
    const marco = opts.landmark?.(i);
    if (marco) {
      // do lado oposto à árvore, mais perto da trilha: os dois dividem o quadro
      marco.position.copy(aoLado(u, -flanco * 15));
      scene.add(marco);
      marcos.push(marco);
    }
  });

  const post = createFogPost(renderer, scene, camera, {
    trail: opts.reduce ? 0 : opts.trail,
    grain: opts.grain,
    light: opts.light,
  });

  const resize = () => {
    const w = Math.max(1, canvas.clientWidth);
    const h = Math.max(1, canvas.clientHeight);
    renderer.setSize(w, h, false);
    post.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    pedir();
  };
  const ro = new ResizeObserver(resize);
  ro.observe(canvas);

  const alvo = { p: 0, px: 0, py: 0 };
  const atual = { p: 0, px: 0, py: 0 };
  const posCam = new THREE.Vector3();
  const olhar = new THREE.Vector3();
  const relogio = new THREE.Clock();
  let visivel = false;
  let raf = 0;

  const quadro = () => {
    const t = relogio.getElapsedTime();
    const k = opts.reduce ? 1 : 0.055;
    atual.p += (alvo.p - atual.p) * k;
    atual.px += (alvo.px - atual.px) * 0.04;
    atual.py += (alvo.py - atual.py) * 0.04;

    // 0.995 e não 1: `getTangentAt(1)` na ponta da curva aberta vira o olhar
    // para o lado no último quadro da caminhada.
    const u = THREE.MathUtils.clamp(atual.p, 0, 0.995);
    trilha.getPointAt(u, posCam);
    // a respiração de quem caminha: sobe e desce quase nada
    camera.position.set(posCam.x, 13 + (opts.reduce ? 0 : Math.sin(t * 0.9) * 0.35), posCam.z);
    aoLado(u + 0.03, atual.px * 40, olhar);
    olhar.y = 16 - atual.py * 10;
    camera.lookAt(olhar);

    if (!opts.reduce) {
      variantes.forEach((v) => v.update(t));
      marcos.forEach((m) => {
        const spin = Number(m.userData.spin) || 0;
        if (spin) m.rotation.y = t * spin;
      });
      post.setTime(t);
    }
    post.render();
  };

  const animando = () =>
    visivel &&
    (!opts.reduce ||
      Math.abs(alvo.p - atual.p) > 1e-4 ||
      Math.abs(alvo.px - atual.px) > 1e-3 ||
      Math.abs(alvo.py - atual.py) > 1e-3);

  // `raf` só zera depois do quadro, para um `pedir()` de dentro dele não
  // agendar um segundo laço em paralelo
  const tick = () => {
    quadro();
    raf = animando() ? requestAnimationFrame(tick) : 0;
  };
  function pedir() {
    if (visivel && !raf) raf = requestAnimationFrame(tick);
  }

  resize();

  return {
    setProgress(p) {
      alvo.p = THREE.MathUtils.clamp(p, 0, 1);
      pedir();
    },
    setPointer(x, y) {
      // com movimento reduzido o olhar não segue o ponteiro: é deslocamento
      // de câmera que a pessoa não pediu
      if (opts.reduce) return;
      alvo.px = x;
      alvo.py = y;
      pedir();
    },
    setColors(paper, ink) {
      post.setColors(paper, ink);
      pedir();
    },
    setRunning(on) {
      if (on === visivel) return;
      visivel = on;
      if (on) {
        post.resetTrail();
        pedir();
      } else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    },
    dispose() {
      visivel = false;
      if (raf) cancelAnimationFrame(raf);
      ro.disconnect();
      // os clones só apontam para o que é das variantes (decisão 1)
      variantes.forEach(disposeTree);
      marcos.forEach(disposeTree);
      chaoGeo.dispose();
      chaoMat.dispose();
      sombraGeo.dispose();
      sombraMat.dispose();
      sombraTex.dispose();
      post.dispose();
      releaseRenderer(renderer);
    },
  };
}

"use client";

/**
 * FogGarden — a caminhada por um jardim na névoa, presa ao scroll.
 *
 * Colhido da rota `/jardim` do site da YURA (2026-10). A seção é alta (uma
 * janela de scroll por parada) e o palco fica preso na tela: rolar leva a
 * câmera pela trilha, e cada parada de texto sai da névoa, fica, e volta para
 * ela. Nenhuma cor própria — a cena é cinza até o duotone do `fog-post` pintar
 * com `--background` e `--foreground`.
 *
 * Decisões que sobrevivem à colheita:
 *
 * 1. **Mola antes de qualquer `useTransform`.** `useScroll` direto num
 *    `useTransform` de opacidade é acelerado pelo ScrollTimeline nativo, que
 *    erra a faixa dentro de `position: sticky` — as paradas acendiam na hora
 *    errada. Passar pela `useSpring` tira a cadeia do caminho nativo e ainda dá
 *    passo de caminhada à câmera, em vez do tranco da roda do mouse.
 * 2. **Texto em `mix-blend-difference`.** Sobre a névoa ele lê como tinta;
 *    sobre uma copa escura, em negativo. Nenhuma posição da trilha deixa o
 *    texto ilegível, e ninguém precisa de caixa de vidro atrás da frase. A cor
 *    da camada é o tom MAIS CLARO do duotone (papel no claro, tinta no escuro):
 *    `difference` com cor escura sobre fundo escuro dá preto no preto, e o
 *    texto sumia no dark mode.
 * 3. **Cada parada tem a sua janela.** Parada `i` de `n` acende em torno de
 *    `(i + 0.5) / n`. A primeira já está acesa no carregamento (a seção não abre
 *    vazia) e a última fica — a caminhada termina num lugar, não no nada.
 *    `keep` faz qualquer uma ficar.
 * 4. **Só clica o que se vê.** O conteúdo das paradas apagadas continua no DOM
 *    (leitor de tela lê a sequência inteira), mas `pointer-events` só liga com
 *    a parada acima de 60% de opacidade: link invisível não rouba clique.
 * 5. **Clareiras saem das paradas.** Sem `clearings`, cada parada a partir da
 *    segunda ganha uma clareira um pouco à frente do seu centro — o texto
 *    acende quando a árvore protagonista entra no quadro.
 * 6. **O WebGL só desce perto da tela, e para fora dela.** Mesmo trato do
 *    `fog-tree`: `import()` a 400px da viewport, laço parado fora da tela e com
 *    a aba escondida, modo leve no toque e em tela pequena.
 *
 * Requer `three`, `@dgreenheck/ez-tree` e `framer-motion`.
 */

import * as React from "react";
import {
  motion,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
  type MotionValue,
} from "framer-motion";

import { cn } from "@/lib/utils";
import { onThemeChange, resolveCssColor, type RGB } from "@/lib/css-color";
import type { GardenLandmark, GardenScene } from "./garden-scene";

export type { GardenLandmark };

export interface FogGardenStop {
  id: string;
  content: React.ReactNode;
  /** Onde o bloco encosta na horizontal. */
  align?: "start" | "center" | "end";
  /** Fica aceso depois da sua janela, em vez de voltar para a névoa. */
  keep?: boolean;
}

export interface FogGardenProps extends Omit<React.HTMLAttributes<HTMLElement>, "children"> {
  stops: FogGardenStop[];
  /** Comprimento de scroll de cada parada. A seção mede `n × heightPerStop`. */
  heightPerStop?: string;
  /**
   * Altura do palco preso. Com `container`, o padrão é a altura do container
   * (medida), porque `svh` é da janela e não do scroller.
   */
  viewport?: string;
  /**
   * Posições de plantio ao longo da trilha. O modo leve usa 60% disso.
   * @min 8
   * @max 140
   * @step 1
   */
  density?: number;
  /** Pontos 0..1 da trilha com clareira. Padrão: derivados das paradas. */
  clearings?: number[];
  /**
   * Objeto para cada clareira (ver `GardenLandmark`). Lido uma vez, quando a
   * cena nasce: uma função inline mudaria a cada render e replantaria o jardim.
   */
  landmark?: GardenLandmark;
  /** Contador "01 / 05" no canto. */
  counter?: boolean;
  /**
   * Semente do plantio. Mesma semente, mesmo jardim.
   * @min 1
   * @max 9999
   * @step 1
   */
  seed?: number;
  paper?: string;
  ink?: string;
  /**
   * Rastro de longa exposição. 0 desliga.
   * @min 0
   * @max 0.98
   * @step 0.01
   */
  trail?: number;
  /**
   * Grão de película.
   * @min 0
   * @max 0.2
   * @step 0.01
   */
  grain?: number;
  /**
   * Scroller que não é a janela (um painel com `overflow: auto`). O progresso
   * passa a ser medido nele.
   */
  container?: React.RefObject<HTMLElement | null>;
}

const ALIGN = {
  start: "items-start text-left",
  center: "items-center text-center",
  end: "items-end text-right",
} as const;

const pad = (n: number) => String(n).padStart(2, "0");

/** Luminância relativa aproximada — só para escolher o tom claro do par. */
const luma = ([r, g, b]: RGB) => 0.2126 * r + 0.7152 * g + 0.0722 * b;
const toCss = ([r, g, b]: RGB) =>
  `rgb(${Math.round(r * 255)} ${Math.round(g * 255)} ${Math.round(b * 255)})`;

const prefersLight = () =>
  window.matchMedia("(pointer: coarse)").matches || window.innerWidth < 768;

export function FogGarden({
  stops,
  heightPerStop = "120vh",
  viewport,
  density = 78,
  clearings,
  landmark,
  counter = true,
  seed = 2026,
  paper = "var(--background)",
  ink = "var(--foreground)",
  trail = 0.84,
  grain = 0.05,
  container,
  className,
  style,
  ...props
}: FogGardenProps) {
  const rootRef = React.useRef<HTMLElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const sceneRef = React.useRef<GardenScene | null>(null);
  const reduce = useReducedMotion() ?? false;
  const n = stops.length;

  const { scrollYProgress } = useScroll({
    target: rootRef,
    container,
    offset: ["start start", "end end"],
  });
  // decisão 1 — passo de caminhada: mais mole que a mola do `fog-tree`
  const prog = useSpring(scrollYProgress, { stiffness: 70, damping: 24, restDelta: 0.0002 });

  React.useEffect(() => {
    sceneRef.current?.setProgress(prog.get());
    return prog.on("change", (v) => sceneRef.current?.setProgress(v));
  }, [prog]);

  // ── Palco: altura da janela, ou do container medido ──────────────────────
  const [measured, setMeasured] = React.useState<string | null>(null);
  React.useEffect(() => {
    const el = container?.current;
    if (!el || viewport) return;
    const ro = new ResizeObserver(() => setMeasured(`${el.clientHeight}px`));
    ro.observe(el);
    return () => ro.disconnect();
  }, [container, viewport]);
  const stageHeight = viewport ?? measured ?? "100svh";

  // ── Clareiras (decisão 5). Chave em string: array novo a cada render do pai
  //    não pode replantar o jardim. ───────────────────────────────────────────
  const clearingKey = clearings
    ? clearings.join(",")
    : Array.from({ length: Math.max(0, n - 1) }, (_, j) =>
        Math.min(0.97, (j + 1.5) / n + 0.02).toFixed(4),
      ).join(",");

  const landmarkRef = React.useRef(landmark);
  landmarkRef.current = landmark;

  // ── Cores (decisão 2) ────────────────────────────────────────────────────
  const applyColors = React.useCallback(() => {
    const el = rootRef.current;
    if (!el) return;
    const p = resolveCssColor(paper, el);
    const k = resolveCssColor(ink, el);
    el.style.setProperty("--fog-garden-text", toCss(luma(p) >= luma(k) ? p : k));
    sceneRef.current?.setColors(p, k);
  }, [paper, ink]);
  const applyRef = React.useRef(applyColors);
  applyRef.current = applyColors;

  React.useEffect(() => {
    applyColors();
    const off = onThemeChange(applyColors);
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change", applyColors);
    return () => {
      off();
      mq.removeEventListener("change", applyColors);
    };
  }, [applyColors]);

  // ── Ciclo de vida da cena (decisão 6) ────────────────────────────────────
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const root = rootRef.current;
    if (!canvas || !root) return;
    let alive = true;
    let loading = false;
    let near = false;

    const running = () => near && document.visibilityState === "visible";
    const sync = () => sceneRef.current?.setRunning(running());

    const io = new IntersectionObserver(
      ([e]) => {
        near = !!e?.isIntersecting;
        if (near && !sceneRef.current && !loading) {
          loading = true;
          import("./garden-scene")
            .then(({ createGardenScene }) => {
              if (!alive) return;
              const scene = createGardenScene(canvas, {
                seed,
                density,
                clearings: clearingKey ? clearingKey.split(",").map(Number) : [],
                landmark: landmarkRef.current,
                trail,
                grain,
                reduce,
                light: prefersLight(),
              });
              sceneRef.current = scene;
              if (!scene) return;
              applyRef.current();
              scene.setProgress(prog.get());
              sync();
            })
            .catch(() => {});
        }
        sync();
      },
      // `root: null` mesmo com container: o IO observa a interseção com a
      // janela, e o container está dentro dela — continua valendo.
      { rootMargin: "400px 0px" },
    );
    io.observe(root);
    document.addEventListener("visibilitychange", sync);

    // Olhar que segue o ponteiro: só com mouse. No toque não há ponteiro
    // pairando, e o "olhar" pularia a cada toque de scroll.
    const fine = window.matchMedia("(pointer: fine)").matches;
    const move = (e: PointerEvent) =>
      sceneRef.current?.setPointer(
        (e.clientX / window.innerWidth) * 2 - 1,
        (e.clientY / window.innerHeight) * 2 - 1,
      );
    if (fine && !reduce) window.addEventListener("pointermove", move, { passive: true });

    return () => {
      alive = false;
      io.disconnect();
      document.removeEventListener("visibilitychange", sync);
      window.removeEventListener("pointermove", move);
      sceneRef.current?.dispose();
      sceneRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seed, density, clearingKey, trail, grain, reduce]);

  const counterText = useTransform(prog, (v) => pad(Math.min(n, Math.floor(v * n) + 1)));

  if (!n) return null;

  return (
    <section
      ref={rootRef}
      className={cn("relative", className)}
      style={{ height: `calc(${n} * ${heightPerStop})`, background: paper, ...style }}
      {...props}
    >
      <div className="sticky top-0 overflow-hidden" style={{ height: stageHeight }}>
        <canvas ref={canvasRef} aria-hidden className="pointer-events-none absolute inset-0 block h-full w-full" />

        <div
          className="pointer-events-none absolute inset-0 mix-blend-difference"
          style={{ color: "var(--fog-garden-text, var(--background))" }}
        >
          {stops.map((s, i) => (
            <Stop key={s.id} stop={s} i={i} n={n} prog={prog} reduce={reduce} />
          ))}

          {counter && n > 1 && (
            <div
              aria-hidden
              className="absolute bottom-6 left-6 flex items-center gap-3 text-[11px] uppercase tracking-[0.12em] md:bottom-8 md:left-10"
            >
              <motion.span className="tabular-nums">{counterText}</motion.span>
              <span className="opacity-50">/ {pad(n)}</span>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

function Stop({
  stop,
  i,
  n,
  prog,
  reduce,
}: {
  stop: FogGardenStop;
  i: number;
  n: number;
  prog: MotionValue<number>;
  reduce: boolean;
}) {
  const c = (i + 0.5) / n;
  const w = 0.5 / n;
  const first = i === 0;
  const stays = stop.keep || i === n - 1;

  // decisão 3 — entra da névoa, fica, volta para ela
  const range = [c - w, c - w * 0.35, c + w * 0.35, c + w];
  const enter = first ? 1 : 0;
  const leave = stays ? 1 : 0;
  const opacity = useTransform(prog, range, [enter, 1, 1, leave]);
  const fogBlur = reduce ? 0 : 14;
  const filter = useTransform(
    prog,
    range,
    [(1 - enter) * fogBlur, 0, 0, (1 - leave) * fogBlur].map((b) => `blur(${b}px)`),
  );
  const drift = reduce ? 0 : 40;
  const y = useTransform(
    prog,
    [c - w, c, c + w],
    [first ? 0 : drift, 0, stays ? 0 : -drift],
  );
  // decisão 4
  const pointerEvents = useTransform(opacity, (o) => (o > 0.6 ? "auto" : "none"));

  return (
    <motion.div
      style={{ opacity, filter, y }}
      className={cn(
        "absolute inset-0 flex flex-col justify-center px-6 md:px-10 lg:px-16",
        ALIGN[stop.align ?? "center"],
      )}
    >
      <motion.div
        style={{ pointerEvents }}
        className={cn("flex max-w-full flex-col", ALIGN[stop.align ?? "center"])}
      >
        {stop.content}
      </motion.div>
    </motion.div>
  );
}

export default FogGarden;
